<script setup lang="ts">
import {useWorkspace} from '../composables/useWorkspace'
import {zh} from '../labels'
const {busy,items,schema,formTags,advanced,draft,saveReview,style,selected,styles,imageUrl}=useWorkspace()
</script>
<template><el-dialog append-to-body class="workspace-dialog asset-dialog" :model-value="!!selected" title="素材详情" width="min(720px,90vw)" @close="selected=null"><template v-if="selected"><img class="detail" :src="imageUrl(selected.image_sha)"/><p>人工标签修正（JSON，保留原始AI结果）</p><el-checkbox v-model="advanced" @change="(v:any)=>{if(v)draft=JSON.stringify(formTags,null,2);else{try{formTags=JSON.parse(draft)}catch{advanced=true}}}">高级 JSON 编辑</el-checkbox><el-input v-if="advanced" v-model="draft" type="textarea" :rows="14"/><div v-else class="tag-form-grid"><div v-for="(spec,key) in schema" :key="key" class="tag-form-field" :class="{wide:['description','visual_evidence','inference_evidence','style_evidence'].includes(key)}"><label>{{zh(key)}}</label><el-select v-if="spec.enum||spec.items?.enum" v-model="formTags[key]" :multiple="!!spec.items" placeholder="请选择" style="width:100%"><el-option v-for="v in (spec.enum||spec.items.enum)" :key="v" :value="v" :label="zh(v)"/></el-select><el-switch v-else-if="spec.type==='boolean'" v-model="formTags[key]" active-text="是" inactive-text="否"/><el-input-number v-else-if="spec.type==='number'" v-model="formTags[key]" :min="0" :max="1" :step="0.05"/><el-input v-else-if="spec.type==='string'" v-model="formTags[key]"/><div v-else-if="key==='style_evidence'"><el-input v-for="s in (formTags.styles||[])" :key="s" :placeholder="s+' 视觉依据'" :model-value="formTags.style_evidence?.[s]||''" @update:model-value="(v:string)=>{formTags.style_evidence={...formTags.style_evidence,[s]:v}}"/></div></div></div></template><template #footer><el-button @click="selected=null">取消</el-button><el-button type="primary" :loading="busy" @click="saveReview">保存人工标签</el-button></template></el-dialog></template>
